  woodCost: number;
  supplyCost: number;
  trainingTime: number; // seconds
}

export interface BuildingStats {
  hp: number;
  goldCost: number;
  woodCost: number;
  buildTime: number; // seconds a worker takes to build
  footprintW: number;
  footprintH: number;
  supplyProvided: number;
  attackDamage: number;
  attackRange: number;
  attackCooldown: number; // seconds
  sightRadius: number;
}

export interface Unit {
  id: number;
  type: UnitType;
  faction: Faction;
  x: number; // tile position (continuous)
  y: number;
  hp: number;
  maxHp: number;
