  woodCost: number;
  supplyCost: number;
}

export interface Building {
  id: number;
  type: BuildingType;
  faction: Faction;
  tileX: number; // top-left tile
  tileY: number;
  hp: number;
  maxHp: number;
  state: BuildingState;
  buildProgress: number; // 0..1
