export interface GameState {
  screen: GameScreen;
  map: GameMap;
  units: Map<number, Unit>;
  buildings: Map<number, Building>;
  projectiles: Map<number, Projectile>;
  nextId: number;
  resources: Record<Faction, Resources>;
  fog: FogState[][]; // per-player fog
  time: number;
  paused: boolean;
  speed: number;
  playerFaction: Faction;
  aiFaction: Faction;
  seed: number;
  rng: PRNG;
  // UI state
  selectedUnitIds: number[];
  selectedBuildingId: number | null;
  camera: Vec2;
  controlGroups: Map<number, ControlGroup>;
  // Build placement mode
  buildMode: BuildingType | null;
  buildValid: boolean;
  // Campaign
  campaignSeed: number;
  currentLevel: number;
  levelResults: Map<number, boolean>;
  // Level info
  levelWidth: number;
  levelHeight: number;
  aiDifficulty: number;
  // Start locations
  playerStart: Vec2;
  aiStart: Vec2;
  // Corpse fade
  corpses: { x: number; y: number; faction: Faction; type: string; fadeTimer: number }[];
}

function makeId(state: GameState): number {
  return state.nextId++;
}

// ─── Map generation and start ───

export function createGameState(
  seed: number,
  playerFaction: Faction,
  level: number = 1,
): GameState {
  const rng = new PRNG(seed);
  const campaignSeed = seed;

  // Level configuration
  const mapSizes = [
    { w: 32, h: 32 },
    { w: 48, h: 48 },
    { w: 64, h: 64 },
    { w: 80, h: 80 },
    { w: 96, h: 96 },
  ];
  const levelIdx = Math.min(level - 1, 4);
  const { w, h } = mapSizes[levelIdx];
  const aiDifficulty = level;

  const mapSeed = rng.nextInt(0, 0x7fffffff);
  const map = generateMap(w, h, mapSeed);

  // Find start locations
  const starts = findStartLocations(map);
  const playerStart = starts[0];
  const aiStart = starts[1];

  const state: GameState = {
    screen: GameScreen.Playing,
    map,
    units: new Map(),
    buildings: new Map(),
    projectiles: new Map(),
    nextId: 1,
    resources: {
      [Faction.Human]: { gold: 400, wood: 200 },
      [Faction.Orc]: { gold: 400 + (aiDifficulty - 1) * 100, wood: 200 + (aiDifficulty - 1) * 50 },
    },
    fog: createFog(w, h),
    time: 0,
    paused: false,
    speed: 1,
    playerFaction,
    aiFaction: playerFaction === Faction.Human ? Faction.Orc : Faction.Human,
    seed,
    rng,
    selectedUnitIds: [],
    selectedBuildingId: null,
    camera: { x: playerStart.x - 10, y: playerStart.y - 8 },
    controlGroups: new Map(),
    buildMode: null,
    buildValid: false,
    campaignSeed,
    currentLevel: level,
    levelResults: new Map(),
    levelWidth: w,
    levelHeight: h,
    aiDifficulty,
    playerStart,
    aiStart,
    corpses: [],
  };

  // Place starting buildings and units for both factions
  placeStartingEntities(state, Faction.Human, playerStart, playerFaction === Faction.Human);
  placeStartingEntities(state, Faction.Orc, aiStart, playerFaction === Faction.Orc);

  return state;
}

function createFog(w: number, h: number): FogState[][] {
  const fog: FogState[][] = [];
  for (let y = 0; y < h; y++) {
    fog[y] = new Array(w).fill(FogState.Unexplored);
  }
  return fog;
}

function findStartLocations(map: GameMap): Vec2[] {
  // Find two far-apart buildable areas in opposite quadrants
  const w = map.width;
  const h = map.height;

  const findCenter = (xMin: number, xMax: number, yMin: number, yMax: number): Vec2 => {
    let best: Vec2 | null = null;
    let bestScore = -1;
    for (let y = yMin; y < yMax; y++) {
      for (let x = xMin; x < xMax; x++) {
        if (WALKABLE_TILES.has(map.tiles[y][x].type)) {
          const score = countWalkableAround(map, x, y, 5);
          if (score > bestScore) {
            bestScore = score;
            best = { x, y };
          }
        }
      }
    }
    return best ?? { x: Math.floor((xMin + xMax) / 2), y: Math.floor((yMin + yMax) / 2) };
  };

  const p1 = findCenter(4, Math.floor(w / 2), 4, Math.floor(h / 2));
  const p2 = findCenter(Math.floor(w / 2), w - 4, Math.floor(h / 2), h - 4);

  return [p1, p2];
}

function countWalkableAround(map: GameMap, cx: number, cy: number, r: number): number {
  let count = 0;
  for (let dy = -r; dy <= r; dy++) {
    for (let dx = -r; dx <= r; dx++) {
      const x = cx + dx;
      const y = cy + dy;
      if (x < 0 || x >= map.width || y < 0 || y >= map.height) continue;
      if (WALKABLE_TILES.has(map.tiles[y][x].type)) count++;
    }
  }
  return count;
}

function placeStartingEntities(state: GameState, faction: Faction, start: Vec2, isPlayer: boolean): void {
  // Place Town Hall
  const hallStats = BUILDING_STATS[BuildingType.TownHall];
  const hall = createBuilding(state, BuildingType.TownHall, faction, start.x - 1, start.y - 1);
  hall.state = BuildingState.Complete;
  hall.buildProgress = 1;
  hall.hp = hall.maxHp;

  // Place 3 Workers near the Town Hall
  for (let i = 0; i < 3; i++) {
    const wx = start.x + i - 1;
    const wy = start.y + 2;
    const worker = createUnit(state, UnitType.Worker, faction, wx, wy);
  }
}

// ─── Entity creation ───

export function createUnit(state: GameState, type: UnitType, faction: Faction, x: number, y: number): Unit {
  const stats = UNIT_STATS[type];
  const unit: Unit = {
    id: makeId(state),
    type,
    faction,
    x,
    y,
    hp: stats.hp,
    maxHp: stats.hp,
    armor: stats.armor,
    attackDamage: stats.attackDamage,
    attackRange: stats.attackRange,
    attackCooldown: stats.attackCooldown,
    cooldownRemaining: 0,
    moveSpeed: stats.moveSpeed,
    sightRadius: stats.sightRadius,
    state: UnitState.Idle,
    targetId: null,
    targetPos: null,
    path: [],
    carryingType: null,
    carryingAmount: 0,
    rallyPoint: null,
    goldCost: stats.goldCost,
    woodCost: stats.woodCost,
    supplyCost: stats.supplyCost,
  };
  state.units.set(unit.id, unit);
  return unit;
}

export function createBuilding(state: GameState, type: BuildingType, faction: Faction, tileX: number, tileY: number): Building {
  const stats = BUILDING_STATS[type];
  const building: Building = {
    id: makeId(state),
    type,
    faction,
    tileX,
    tileY,
    hp: Math.ceil(stats.hp * 0.1), // starts at 10% HP when constructing
    maxHp: stats.hp,
    state: BuildingState.Constructing,
    buildProgress: 0,
    trainingQueue: [],
    rallyPoint: null,
    attackDamage: stats.attackDamage,
    attackRange: stats.attackRange,
    attackCooldown: stats.attackCooldown,
    cooldownRemaining: 0,
    sightRadius: stats.sightRadius,
  };

  // Place building on map tiles
  for (let dy = 0; dy < stats.footprintH; dy++) {
    for (let dx = 0; dx < stats.footprintW; dx++) {
      const tx = tileX + dx;
      const ty = tileY + dy;
      if (tx >= 0 && tx < state.map.width && ty >= 0 && ty < state.map.height) {
        state.map.tiles[ty][tx].buildingId = building.id;
      }
    }
  }

  state.buildings.set(building.id, building);
  return building;
}

// ─── Simulation tick ───

export function simulateTick(state: GameState): void {
  if (state.paused || state.screen !== GameScreen.Playing) return;

  const dt = TICK_DURATION * state.speed;

  // Update units
  for (const unit of state.units.values()) {
    if (unit.state === UnitState.Dead) continue;
    updateUnit(state, unit, dt);
  }

  // Remove dead units
  for (const [id, unit] of state.units) {
    if (unit.state === UnitState.Dead) {
      state.corpses.push({
        x: unit.x,
        y: unit.y,
        faction: unit.faction,
        type: unit.type,
        fadeTimer: 3,
      });
      state.units.delete(id);
    }
  }

  // Update buildings
  for (const building of state.buildings.values()) {
    if (building.state === BuildingState.Destroyed) continue;
    updateBuilding(state, building, dt);
  }

  // Update projectiles
  updateProjectiles(state, dt);

  // Update corpses
  for (let i = state.corpses.length - 1; i >= 0; i--) {
    state.corpses[i].fadeTimer -= dt;
    if (state.corpses[i].fadeTimer <= 0) {
      state.corpses.splice(i, 1);
    }
  }

  // Remove destroyed buildings from map
  for (const [id, building] of state.buildings) {
    if (building.state === BuildingState.Destroyed) {
      const stats = BUILDING_STATS[building.type];
      for (let dy = 0; dy < stats.footprintH; dy++) {
        for (let dx = 0; dx < stats.footprintW; dx++) {
          const tx = building.tileX + dx;
          const ty = building.tileY + dy;
          if (tx >= 0 && tx < state.map.width && ty >= 0 && ty < state.map.height) {
            if (state.map.tiles[ty][tx].buildingId === id) {
              state.map.tiles[ty][tx].buildingId = null;
            }
          }
        }
      }
      state.buildings.delete(id);
    }
  }

  // Update fog of war
  updateFog(state);

  // Check win/lose conditions
  checkWinLose(state);

  // Update time
  state.time += dt;
}

// ─── Unit update ───

function updateUnit(state: GameState, unit: Unit, dt: number): void {
  // Reduce cooldown
  if (unit.cooldownRemaining > 0) {
    unit.cooldownRemaining = Math.max(0, unit.cooldownRemaining - dt);
  }

  switch (unit.state) {
    case UnitState.Idle:
      updateIdleUnit(state, unit, dt);
      break;
    case UnitState.Moving:
      updateMovingUnit(state, unit, dt);
      break;
    case UnitState.Attacking:
      updateAttackingUnit(state, unit, dt);
      break;
    case UnitState.Harvesting:
      updateHarvestingUnit(state, unit, dt);
      break;
    case UnitState.Returning:
      updateReturningUnit(state, unit, dt);
      break;
    case UnitState.Building:
      updateBuildingUnit(state, unit, dt);
      break;
    case UnitState.Repairing:
      updateRepairingUnit(state, unit, dt);
      break;
  }
}

function updateIdleUnit(state: GameState, unit: Unit, dt: number): void {
  // Auto-acquire nearby enemies
  if (unit.attackDamage > 0) {
    const target = findNearestEnemy(state, unit, unit.sightRadius + GUARD_ACQUIRE_RADIUS_ADD);
    if (target) {
      unit.targetId = target.id;
      unit.state = UnitState.Attacking;
    }
  }
}

function updateMovingUnit(state: GameState, unit: Unit, dt: number): void {
  if (unit.path.length === 0 && unit.targetPos) {
    // Recalculate path
    unit.path = findPath(state.map, Math.round(unit.x), Math.round(unit.y),
      unit.targetPos.x, unit.targetPos.y);
    if (unit.path.length === 0) {
      unit.state = UnitState.Idle;
      unit.targetPos = null;
      return;
    }
  }

  if (unit.path.length === 0) {
    unit.state = UnitState.Idle;
    unit.targetPos = null;
    return;
  }

  // Move along path
  const speed = unit.moveSpeed * dt;
  let remaining = speed;

  while (remaining > 0 && unit.path.length > 0) {
    const next = unit.path[0];
    const dx = next.x - unit.x;
    const dy = next.y - unit.y;
    const dist = Math.sqrt(dx * dx + dy * dy);

    if (dist < 0.05) {
      unit.x = next.x;
      unit.y = next.y;
      unit.path.shift();
      continue;
    }

    if (dist <= remaining) {
      unit.x = next.x;
      unit.y = next.y;
      remaining -= dist;
      unit.path.shift();
    } else {
      unit.x += (dx / dist) * remaining;
      unit.y += (dy / dist) * remaining;
      remaining = 0;
    }
  }

  // Check if arrived at destination
  if (unit.path.length === 0) {
    if (unit.targetPos) {
      unit.x = Math.round(unit.x);
      unit.y = Math.round(unit.y);
    }
    unit.state = UnitState.Idle;
    unit.targetPos = null;
  }
}

function updateAttackingUnit(state: GameState, unit: Unit, dt: number): void {
  // If we have a target, verify it still exists and is in range
  if (unit.targetId !== null) {
    const target = getEntity(state, unit.targetId);
    if (!target || (isUnit(target) && target.state === UnitState.Dead) ||
      (isBuilding(target) && target.state === BuildingState.Destroyed)) {
      unit.targetId = null;
      unit.state = UnitState.Idle;
      return;
    }

    const targetPos = getEntityPosition(target);
    const dist = distance(unit.x, unit.y, targetPos.x, targetPos.y);

    if (dist > unit.attackRange + 0.5) {
      // Move toward target
      if (unit.path.length === 0 || unit.targetPos?.x !== Math.round(targetPos.x) ||
        unit.targetPos?.y !== Math.round(targetPos.y)) {
        unit.targetPos = { x: Math.round(targetPos.x), y: Math.round(targetPos.y) };
        unit.path = findPath(state.map, Math.round(unit.x), Math.round(unit.y),
          Math.round(targetPos.x), Math.round(targetPos.y));
      }
      unit.state = UnitState.Moving;
      return;
    }

    // In range — attack
    if (unit.cooldownRemaining <= 0) {
      performAttack(state, unit, target);
      unit.cooldownRemaining = unit.attackCooldown;
    }
  } else {
    // No target — try to find one
    const target = findNearestEnemy(state, unit, unit.sightRadius);
    if (target) {
      unit.targetId = target.id;
    } else {
      unit.state = UnitState.Idle;
    }
  }
}

function updateHarvestingUnit(state: GameState, unit: Unit, dt: number): void {
  const tx = Math.round(unit.x);
  const ty = Math.round(unit.y);

  if (tx < 0 || tx >= state.map.width || ty < 0 || ty >= state.map.height) {
    unit.state = UnitState.Idle;
    return;
  }

  const tile = state.map.tiles[ty][tx];

  if (unit.carryingAmount >= WORKER_CARRY_AMOUNT) {
    // Full — return to drop-off
    unit.state = UnitState.Returning;
    return;
  }

  if (tile.type === TileType.GoldMine && tile.resourceAmount > 0) {
    // Harvest gold
    const amount = Math.min(WORKER_HARVEST_RATE * dt, tile.resourceAmount, WORKER_CARRY_AMOUNT - unit.carryingAmount);
    tile.resourceAmount -= amount;
    unit.carryingType = 'gold';
    unit.carryingAmount += amount;

    if (unit.carryingAmount >= WORKER_CARRY_AMOUNT || tile.resourceAmount <= 0) {
      if (tile.resourceAmount <= 0) {
        // Depleted gold mine — convert to dirt
        tile.type = TileType.Dirt;
        tile.resourceAmount = 0;
      }
      unit.state = UnitState.Returning;
    }
  } else if (tile.type === TileType.Forest && tile.resourceAmount > 0) {
    // Harvest wood
    const amount = Math.min(WORKER_HARVEST_RATE * dt, tile.resourceAmount, WORKER_CARRY_AMOUNT - unit.carryingAmount);
    tile.resourceAmount -= amount;
    unit.carryingType = 'wood';
    unit.carryingAmount += amount;

    if (unit.carryingAmount >= WORKER_CARRY_AMOUNT || tile.resourceAmount <= 0) {
      if (tile.resourceAmount <= 0) {
        // Depleted forest — convert to grass
        tile.type = TileType.Grass;
        tile.resourceAmount = 0;
      }
      unit.state = UnitState.Returning;
    }
  } else {
    // Not on a resource tile — move to target
    if (unit.targetPos) {
      unit.state = UnitState.Moving;
    } else {
      unit.state = UnitState.Idle;
    }
  }
}

function updateReturningUnit(state: GameState, unit: Unit, dt: number): void {
  // Find nearest drop-off building (Town Hall or Lumber Mill)
  const dropOff = findNearestDropoff(state, unit);
  if (!dropOff) {
    unit.state = UnitState.Idle;
    return;
  }

  const dropPos = getEntityPosition(dropOff);
  const dist = distance(unit.x, unit.y, dropPos.x, dropPos.y);

  if (dist > 2) {
    // Move toward drop-off
    if (unit.path.length === 0 || !unit.targetPos ||
      unit.targetPos.x !== Math.round(dropPos.x) ||
      unit.targetPos.y !== Math.round(dropPos.y)) {
      unit.targetPos = { x: Math.round(dropPos.x), y: Math.round(dropPos.y) };
      unit.path = findPath(state.map, Math.round(unit.x), Math.round(unit.y),
        Math.round(dropPos.x), Math.round(dropPos.y));
    }
    // Stay in returning state but move
    const speed = unit.moveSpeed * dt;
    if (unit.path.length > 0) {
      const next = unit.path[0];
      const dx = next.x - unit.x;
      const dy = next.y - unit.y;
      const d = Math.sqrt(dx * dx + dy * dy);
      if (d <= speed) {
        unit.x = next.x;
        unit.y = next.y;
        unit.path.shift();
      } else {
        unit.x += (dx / d) * speed;
        unit.y += (dy / d) * speed;
      }
    }
    return;
  }

  // Deposit resources
  if (unit.carryingType === 'gold') {
    state.resources[unit.faction].gold += unit.carryingAmount;
  } else if (unit.carryingType === 'wood') {
    state.resources[unit.faction].wood += unit.carryingAmount;
  }
  unit.carryingAmount = 0;
  unit.carryingType = null;

  // Go back to harvesting if there's a resource target
  if (unit.targetPos) {
    unit.state = UnitState.Moving;
  } else {
    unit.state = UnitState.Idle;
  }
}

function updateBuildingUnit(state: GameState, unit: Unit, dt: number): void {
  // Find the building we're constructing
  if (unit.targetId === null) {
    unit.state = UnitState.Idle;
    return;
  }

  const building = state.buildings.get(unit.targetId);
  if (!building || building.state === BuildingState.Destroyed) {
    unit.state = UnitState.Idle;
    unit.targetId = null;
    return;
  }

  const dist = distance(unit.x, unit.y, building.tileX + 0.5, building.tileY + 0.5);

  if (dist > 3) {
    // Move to building
    unit.targetPos = { x: building.tileX, y: building.tileY };
    if (unit.path.length === 0) {
      unit.path = findPath(state.map, Math.round(unit.x), Math.round(unit.y),
        building.tileX, building.tileY);
    }
    const speed = unit.moveSpeed * dt;
    moveAlongPath(unit, speed);
    return;
  }

  // Construct
  const buildRate = WORKER_BUILD_RATE;
  building.buildProgress += buildRate * dt;
  building.hp = Math.ceil(building.maxHp * building.buildProgress);

  if (building.buildProgress >= 1) {
    building.buildProgress = 1;
    building.hp = building.maxHp;
    building.state = BuildingState.Complete;
    unit.state = UnitState.Idle;
    unit.targetId = null;
  }
}

function updateRepairingUnit(state: GameState, unit: Unit, dt: number): void {
  if (unit.targetId === null) {
    unit.state = UnitState.Idle;
    return;
  }

  const building = state.buildings.get(unit.targetId);
  if (!building || building.state === BuildingState.Destroyed) {
    unit.state = UnitState.Idle;
    unit.targetId = null;
    return;
  }

  const dist = distance(unit.x, unit.y, building.tileX + 0.5, building.tileY + 0.5);
  if (dist > 3) {
    unit.targetPos = { x: building.tileX, y: building.tileY };
    if (unit.path.length === 0) {
      unit.path = findPath(state.map, Math.round(unit.x), Math.round(unit.y),
        building.tileX, building.tileY);
    }
    const speed = unit.moveSpeed * dt;
    moveAlongPath(unit, speed);
    return;
  }

  // Repair
  building.hp = Math.min(building.maxHp, building.hp + WORKER_REPAIR_RATE * dt);
  if (building.hp >= building.maxHp) {
    unit.state = UnitState.Idle;
    unit.targetId = null;
  }
}

// ─── Building update ───

function updateBuilding(state: GameState, building: Building, dt: number): void {
  // Guard tower attacks
  if (building.type === BuildingType.GuardTower && building.state === BuildingState.Complete) {
    if (building.attackDamage > 0 && building.attackRange > 0) {
      updateTowerAttack(state, building, dt);
    }
  }

  // Training
  if (building.trainingQueue.length > 0 && building.state === BuildingState.Complete) {
    const item = building.trainingQueue[0];
    item.progress += dt / item.totalTime;

    if (item.progress >= 1) {
      // Unit trained — spawn it
      spawnTrainedUnit(state, building, item.unitType);
      building.trainingQueue.shift();
    }
  }
}

function updateTowerAttack(state: GameState, tower: Building, dt: number): void {
  if (tower.cooldownRemaining > 0) {
    tower.cooldownRemaining -= dt;
    return;
  }

  // Find nearest enemy in range
  const cx = tower.tileX + 0.5;
  const cy = tower.tileY + 0.5;

  let nearestEnemy: Unit | null = null;
  let nearestDist = Infinity;

  for (const unit of state.units.values()) {
    if (unit.faction === tower.faction || unit.state === UnitState.Dead) continue;
    const dist = distance(cx, cy, unit.x, unit.y);
    if (dist <= tower.attackRange && dist < nearestDist) {
      nearestDist = dist;
      nearestEnemy = unit;
    }
  }

  if (nearestEnemy) {
    // Fire projectile
    const projectile: Projectile = {
      id: makeId(state),
      x: cx,
      y: cy,
      targetId: nearestEnemy.id,
      damage: tower.attackDamage,
      speed: PROJECTILE_SPEED,
      faction: tower.faction,
      sourceId: tower.id,
    };
    state.projectiles.set(projectile.id, projectile);
    tower.cooldownRemaining = tower.attackCooldown;
  }
}

function spawnTrainedUnit(state: GameState, building: Building, unitType: UnitType): void {
  // Find a walkable tile near the building to spawn the unit
  const spawnPos = findSpawnPosition(state, building);
  if (!spawnPos) return;

  const unit = createUnit(state, unitType, building.faction, spawnPos.x, spawnPos.y);

  // If rally point set, move there
  if (building.rallyPoint) {
    unit.targetPos = { ...building.rallyPoint };
    unit.path = findPath(state.map, spawnPos.x, spawnPos.y,
      building.rallyPoint.x, building.rallyPoint.y);
    if (unit.path.length > 0) {
      unit.state = UnitState.Moving;
    }
  }
}

function findSpawnPosition(state: GameState, building: Building): Vec2 | null {
  const stats = BUILDING_STATS[building.type];
  // Try tiles around the building
  for (let dy = -1; dy <= stats.footprintH; dy++) {
    for (let dx = -1; dx <= stats.footprintW; dx++) {
      const x = building.tileX + dx;
      const y = building.tileY + dy;
      if (x < 0 || x >= state.map.width || y < 0 || y >= state.map.height) continue;
      const tile = state.map.tiles[y][x];
      if (WALKABLE_TILES.has(tile.type) && tile.buildingId === null) {
        // Check no unit occupies this tile
        let occupied = false;
        for (const u of state.units.values()) {
          if (Math.round(u.x) === x && Math.round(u.y) === y) {
            occupied = true;
            break;
          }
        }
        if (!occupied) return { x, y };
      }
    }
  }
  return null;
}

// ─── Combat ───

function performAttack(state: GameState, attacker: Unit, target: Unit | Building): void {
  if (attacker.attackRange > 1) {
    // Ranged attack — spawn projectile
    const proj: Projectile = {
      id: makeId(state),
      x: attacker.x,
      y: attacker.y,
      targetId: target.id,
      damage: attacker.attackDamage,
      speed: PROJECTILE_SPEED,
      faction: attacker.faction,
      sourceId: attacker.id,
    };
    state.projectiles.set(proj.id, proj);
  } else {
    // Melee attack — apply damage directly
    const armor = isUnit(target) ? (target as Unit).armor : 0;
    const damage = Math.max(1, attacker.attackDamage - armor);
    applyDamage(state, target, damage);
  }
}

function applyDamage(state: GameState, target: Unit | Building, damage: number): void {
  if (isUnit(target)) {
    target.hp -= damage;
    if (target.hp <= 0) {
      target.hp = 0;
      target.state = UnitState.Dead;
    }
  } else {
    target.hp -= damage;
    if (target.hp <= 0) {
      target.hp = 0;
      target.state = BuildingState.Destroyed;
    }
  }
}

function updateProjectiles(state: GameState, dt: number): void {
  for (const [id, proj] of state.projectiles) {
    const target = getEntity(state, proj.targetId);
    if (!target) {
      state.projectiles.delete(id);
      continue;
    }

    const targetPos = getEntityPosition(target);
    const dx = targetPos.x - proj.x;
    const dy = targetPos.y - proj.y;
    const dist = Math.sqrt(dx * dx + dy * dy);

    if (dist <= proj.speed * dt) {
      // Hit
      const armor = isUnit(target) ? (target as Unit).armor : 0;
      const damage = Math.max(1, proj.damage - armor);
      applyDamage(state, target, damage);
      state.projectiles.delete(id);
    } else {
      // Move toward target
      proj.x += (dx / dist) * proj.speed * dt;
      proj.y += (dy / dist) * proj.speed * dt;
    }
  }
}

// ─── Fog of war ───

function updateFog(state: GameState): void {
  const w = state.map.width;
  const h = state.map.height;

  // Mark all visible as explored
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      if (state.fog[y][x] === FogState.Visible) {
        state.fog[y][x] = FogState.Explored;
      }
    }
  }

  // Mark tiles visible by player's units and buildings
  const markVisible = (cx: number, cy: number, radius: number) => {
    const r = Math.ceil(radius);
    for (let dy = -r; dy <= r; dy++) {
      for (let dx = -r; dx <= r; dx++) {
        if (dx * dx + dy * dy > radius * radius) continue;
        const x = Math.round(cx) + dx;
        const y = Math.round(cy) + dy;
        if (x < 0 || x >= w || y < 0 || y >= h) continue;
        state.fog[y][x] = FogState.Visible;
      }
    }
  };

  for (const unit of state.units.values()) {
    if (unit.faction === state.playerFaction && unit.state !== UnitState.Dead) {
      markVisible(unit.x, unit.y, unit.sightRadius);
    }
  }

  for (const building of state.buildings.values()) {
    if (building.faction === state.playerFaction && building.state !== BuildingState.Destroyed) {
      const stats = BUILDING_STATS[building.type];
      const cx = building.tileX + stats.footprintW / 2;
      const cy = building.tileY + stats.footprintH / 2;
      markVisible(cx, cy, building.sightRadius || stats.footprintW);
    }
  }
}

// ─── Win/Lose ───

function checkWinLose(state: GameState): void {
  const playerBuildings = [...state.buildings.values()].filter(b => b.faction === state.playerFaction && b.state !== BuildingState.Destroyed);
  const aiBuildings = [...state.buildings.values()].filter(b => b.faction === state.aiFaction && b.state !== BuildingState.Destroyed);

  if (playerBuildings.length === 0) {
    state.screen = GameScreen.Defeat;
  } else if (aiBuildings.length === 0) {
    state.screen = GameScreen.Victory;
  }
}

// ─── Helper functions ───

function findNearestEnemy(state: GameState, unit: Unit, radius: number): Unit | Building | null {
  let nearest: Unit | Building | null = null;
  let nearestDist = Infinity;

  for (const other of state.units.values()) {
    if (other.faction === unit.faction || other.state === UnitState.Dead) continue;
    const dist = distance(unit.x, unit.y, other.x, other.y);
    if (dist <= radius && dist < nearestDist) {
      nearestDist = dist;
      nearest = other;
    }
  }

  // Also check enemy buildings (for attack-move)
  for (const building of state.buildings.values()) {
    if (building.faction === unit.faction || building.state === BuildingState.Destroyed) continue;
    const stats = BUILDING_STATS[building.type];
    const cx = building.tileX + stats.footprintW / 2;
    const cy = building.tileY + stats.footprintH / 2;
    const dist = distance(unit.x, unit.y, cx, cy);
    if (dist <= radius && dist < nearestDist) {
      nearestDist = dist;
      nearest = building;
    }
  }

  return nearest;
}

function findNearestDropoff(state: GameState, unit: Unit): Building | null {
  let nearest: Building | null = null;
  let nearestDist = Infinity;

  for (const building of state.buildings.values()) {
    if (building.faction !== unit.faction || building.state !== BuildingState.Complete) continue;
    if (building.type !== BuildingType.TownHall && building.type !== BuildingType.LumberMill) continue;

    // Only gold drop-off at Town Hall, wood at both
    if (unit.carryingType === 'gold' && building.type !== BuildingType.TownHall) continue;

    const stats = BUILDING_STATS[building.type];
    const cx = building.tileX + stats.footprintW / 2;
    const cy = building.tileY + stats.footprintH / 2;
    const dist = distance(unit.x, unit.y, cx, cy);
    if (dist < nearestDist) {
      nearestDist = dist;
      nearest = building;
    }
  }

  return nearest;
}

function moveAlongPath(unit: Unit, speed: number): void {
  if (unit.path.length === 0) return;

  let remaining = speed;
  while (remaining > 0 && unit.path.length > 0) {
    const next = unit.path[0];
    const dx = next.x - unit.x;
    const dy = next.y - unit.y;
    const dist = Math.sqrt(dx * dx + dy * dy);

    if (dist < 0.05) {
      unit.x = next.x;
      unit.y = next.y;
      unit.path.shift();
      continue;
    }

    if (dist <= remaining) {
      unit.x = next.x;
      unit.y = next.y;
      remaining -= dist;
      unit.path.shift();
    } else {
      unit.x += (dx / dist) * remaining;
      unit.y += (dy / dist) * remaining;
      remaining = 0;
    }
  }
}

function getEntity(state: GameState, id: number): Unit | Building | null {
  return state.units.get(id) ?? state.buildings.get(id) ?? null;
}

function getEntityPosition(entity: Unit | Building): Vec2 {
  if (isUnit(entity)) {
    return { x: (entity as Unit).x, y: (entity as Unit).y };
  }
  const b = entity as Building;
  const stats = BUILDING_STATS[b.type];
  return { x: b.tileX + stats.footprintW / 2, y: b.tileY + stats.footprintH / 2 };
}

function isUnit(entity: Unit | Building): entity is Unit {
  return 'state' in entity && typeof (entity as Unit).moveSpeed === 'number';
}

function distance(x1: number, y1: number, x2: number, y2: number): number {
  const dx = x2 - x1;
  const dy = y2 - y1;
  return Math.sqrt(dx * dx + dy * dy);
}

// ─── Command processing ───

export function issueMoveCommand(state: GameState, unitIds: number[], x: number, y: number): void {
  for (const id of unitIds) {
    const unit = state.units.get(id);
    if (!unit || unit.state === UnitState.Dead) continue;
    unit.targetPos = { x: Math.round(x), y: Math.round(y) };
    unit.path = findPath(state.map, Math.round(unit.x), Math.round(unit.y), Math.round(x), Math.round(y));
    unit.state = UnitState.Moving;
    unit.targetId = null;
  }
}

export function issueAttackCommand(state: GameState, unitIds: number[], targetId: number): void {
  for (const id of unitIds) {
    const unit = state.units.get(id);
    if (!unit || unit.state === UnitState.Dead) continue;
    unit.targetId = targetId;
    unit.state = UnitState.Attacking;
    unit.targetPos = null;
    unit.path = [];
  }
}

export function issueAttackMoveCommand(state: GameState, unitIds: number[], x: number, y: number): void {
  for (const id of unitIds) {
    const unit = state.units.get(id);
    if (!unit || unit.state === UnitState.Dead) continue;
    unit.targetPos = { x: Math.round(x), y: Math.round(y) };
    unit.path = findPath(state.map, Math.round(unit.x), Math.round(unit.y), Math.round(x), Math.round(y));
    unit.state = UnitState.Moving;
    unit.targetId = null;
    // Attack-move: will auto-acquire enemies along the way
  }
}

export function issueHarvestCommand(state: GameState, unitIds: number[], tx: number, ty: number): void {
  for (const id of unitIds) {
    const unit = state.units.get(id);
    if (!unit || unit.state === UnitState.Dead || unit.type !== UnitType.Worker) continue;
    unit.targetPos = { x: Math.round(tx), y: Math.round(ty) };
    unit.path = findPath(state.map, Math.round(unit.x), Math.round(unit.y), Math.round(tx), Math.round(ty));
    unit.state = UnitState.Moving;
    unit.targetId = null;
    // After arriving, will switch to harvesting
  }
}

export function issueBuildCommand(state: GameState, unitId: number, buildingType: BuildingType, tileX: number, tileY: number): void {
  const unit = state.units.get(unitId);
  if (!unit || unit.type !== UnitType.Worker) return;

  const stats = BUILDING_STATS[buildingType];

  // Check resources
  const resources = state.resources[unit.faction];
  if (resources.gold < stats.goldCost || resources.wood < stats.woodCost) return;

  // Check supply for Town Hall (doesn't require supply)
  // Check placement validity
  if (!canPlaceBuilding(state, buildingType, tileX, tileY, unit.faction)) return;

  // Deduct resources
  resources.gold -= stats.goldCost;
  resources.wood -= stats.woodCost;

  // Create building
  const building = createBuilding(state, buildingType, unit.faction, tileX, tileY);

  // Order worker to build
  unit.targetId = building.id;
  unit.state = UnitState.Building;
  unit.targetPos = { x: tileX, y: tileY };
  unit.path = findPath(state.map, Math.round(unit.x), Math.round(unit.y), tileX, tileY);
}

export function issueTrainCommand(state: GameState, buildingId: number, unitType: UnitType): void {
  const building = state.buildings.get(buildingId);
  if (!building || building.state !== BuildingState.Complete) return;

  // Check prerequisites
  const prerequisites = getUnitPrerequisites(unitType);
  for (const prereq of prerequisites) {
    const hasPrereq = [...state.buildings.values()].some(
      b => b.faction === building.faction && b.type === prereq && b.state === BuildingState.Complete
    );
    if (!hasPrereq) return;
  }

  // Check it's the right building
  const requiredBuilding = getTrainingBuilding(unitType);
  if (building.type !== requiredBuilding) return;

  // Check resources
  const stats = UNIT_STATS[unitType];
  const resources = state.resources[building.faction];
  if (resources.gold < stats.goldCost || resources.wood < stats.woodCost) return;

  // Check supply
  const supply = getSupply(state, building.faction);
  if (supply.used + stats.supplyCost > supply.cap) return;

  // Deduct resources
  resources.gold -= stats.goldCost;
  resources.wood -= stats.woodCost;

  // Add to training queue
  building.trainingQueue.push({
    unitType,
    progress: 0,
    totalTime: stats.trainingTime,
  });
}

export function issueRepairCommand(state: GameState, unitIds: number[], targetId: number): void {
  for (const id of unitIds) {
    const unit = state.units.get(id);
    if (!unit || unit.type !== UnitType.Worker) continue;
    unit.targetId = targetId;
    unit.state = UnitState.Repairing;
    unit.targetPos = null;
    unit.path = [];
  }
}

export function canPlaceBuilding(state: GameState, type: BuildingType, tileX: number, tileY: number, faction: Faction): boolean {
  const stats = BUILDING_STATS[type];

  // Check bounds
  if (tileX < 0 || tileY < 0 ||
    tileX + stats.footprintW > state.map.width ||
    tileY + stats.footprintH > state.map.height) {
    return false;
  }

  // Check all tiles are buildable and unoccupied
  for (let dy = 0; dy < stats.footprintH; dy++) {
    for (let dx = 0; dx < stats.footprintW; dx++) {
      const tile = state.map.tiles[tileY + dy][tileX + dx];
      if (!WALKABLE_TILES.has(tile.type) || tile.buildingId !== null) {
        return false;
      }
    }
  }

  return true;
}

// ─── Supply ───

export function getSupply(state: GameState, faction: Faction): SupplyInfo {
  let cap = 0;
  let used = 0;

  for (const building of state.buildings.values()) {
    if (building.faction === faction && building.state === BuildingState.Complete) {
      cap += BUILDING_STATS[building.type].supplyProvided;
    }
  }

  for (const unit of state.units.values()) {
    if (unit.faction === faction && unit.state !== UnitState.Dead) {
      used += unit.supplyCost;
    }
  }

  // Also count units in training
  for (const building of state.buildings.values()) {
    if (building.faction === faction) {
      for (const item of building.trainingQueue) {
        used += UNIT_STATS[item.unitType].supplyCost;
      }
    }
  }

  return { used, cap };
}

// ─── AI functions (exported for ai.ts) ───

export function getPlayerStartLocations(state: GameState): { player: Vec2; ai: Vec2 } {
  return { player: state.playerStart, ai: state.aiStart };
}

export function findNearestResource(state: GameState, from: Vec2, type: TileType): Vec2 | null {
  let best: Vec2 | null = null;
  let bestDist = Infinity;

  for (let y = 0; y < state.map.height; y++) {
    for (let x = 0; x < state.map.width; x++) {
      const tile = state.map.tiles[y][x];
      if (tile.type === type && tile.resourceAmount > 0) {
        const dist = distance(from.x, from.y, x, y);
        if (dist < bestDist) {
          bestDist = dist;
          best = { x, y };
        }
      }
    }
  }

  return best;
}

// ─── AI Opponent ───
// Scripted-strategy AI that harvests, builds, trains, and attacks.

import {
  GameState, Faction, UnitType, BuildingType, UnitState, BuildingState, Vec2,
} from './types';
import {
  UNIT_STATS, BUILDING_STATS, WALKABLE_TILES,
} from './constants';
import {
  createUnit, issueMoveCommand, issueTrainCommand, issueBuildCommand,
  canPlaceBuilding, findNearestResource, getSupply, distance,
} from './game';
import { PRNG } from './prng';

interface AIPlan {
  nextBuildOrder: BuildingType | null;
  nextTrainOrder: UnitType | null;
  attackWaveSize: number;
  attackInterval: number; // seconds between waves
  workersPerGold: number;
  workersPerWood: number;
  maxWorkers: number;
}

function getPlan(difficulty: number): AIPlan {
  return {
    nextBuildOrder: null,
    nextTrainOrder: null,
    attackWaveSize: 3 + difficulty * 2,
    attackInterval: Math.max(60, 240 - difficulty * 40), // 4min at diff 1, down to 40s at diff 5
    workersPerGold: 2 + Math.floor(difficulty / 2),
    workersPerWood: 1 + Math.floor(difficulty / 3),
    maxWorkers: 8 + difficulty * 2,
  };
}

export class AIController {
  private faction: Faction;
  private difficulty: number;
  private plan: AIPlan;
  private rng: PRNG;
  private lastAttackTime: number;
  private buildOrderIndex: number;
  private buildOrder: BuildingType[];
  private nextCheckTime: number;
  private harvestAssignments: Map<number, 'gold' | 'wood'>;

  constructor(faction: Faction, difficulty: number, seed: number) {
    this.faction = faction;
    this.difficulty = difficulty;
    this.plan = getPlan(difficulty);
    this.rng = new PRNG(seed);
    this.lastAttackTime = 0;
    this.buildOrderIndex = 0;
    this.nextCheckTime = 5;
    this.harvestAssignments = new Map();
    this.buildOrder = this.createBuildOrder();
  }

  private createBuildOrder(): BuildingType[] {
    // Standard build order: farm, barracks, farm, lumber mill, farm, guard tower, farm, guard tower
    return [
      BuildingType.Farm,
      BuildingType.Barracks,
      BuildingType.Farm,
      BuildingType.LumberMill,
      BuildingType.Farm,
      BuildingType.GuardTower,
      BuildingType.Farm,
      BuildingType.GuardTower,
      BuildingType.Farm,
    ];
  }

  update(state: GameState, dt: number): void {
    const now = state.time;

    if (now < this.nextCheckTime) return;
    this.nextCheckTime = now + 1; // Check every second

    const resources = state.resources[this.faction];
    const supply = getSupply(state, this.faction);
    const myUnits = [...state.units.values()].filter(u => u.faction === this.faction && u.state !== UnitState.Dead);
    const myBuildings = [...state.buildings.values()].filter(b => b.faction === this.faction && b.state !== BuildingState.Destroyed);
    const workers = myUnits.filter(u => u.type === UnitType.Worker);
    const military = myUnits.filter(u => u.type !== UnitType.Worker);

    // 1. Assign idle workers to harvest
    this.assignWorkers(state, workers);

    // 2. Train workers if needed
    this.trainWorkers(state, workers);

    // 3. Build next building
    this.buildNext(state, myBuildings);

    // 4. Train military
    this.trainMilitary(state, military);

    // 5. Attack waves
    this.manageAttacks(state, military);

    // 6. Defend base
    this.defendBase(state, myUnits);
  }

  private assignWorkers(state: GameState, workers: Unit[]): void {
    const goldWorkers = workers.filter(w => this.harvestAssignments.get(w.id) === 'gold');
    const woodWorkers = workers.filter(w => this.harvestAssignments.get(w.id) === 'wood');
    const idleWorkers = workers.filter(w =>
      w.state === UnitState.Idle ||
      (w.carryingAmount === 0 && w.state !== UnitState.Harvesting && w.state !== UnitState.Returning)
    );

    const plan = this.plan;

    for (const worker of idleWorkers) {
      if (goldWorkers.length < plan.workersPerGold) {
        this.harvestAssignments.set(worker.id, 'gold');
        this.sendToHarvest(state, worker, 'gold');
        goldWorkers.push(worker);
      } else if (woodWorkers.length < plan.workersPerWood + plan.workersPerGold) {
        this.harvestAssignments.set(worker.id, 'wood');
        this.sendToHarvest(state, worker, 'wood');
        woodWorkers.push(worker);
      } else if (workers.length >= plan.maxWorkers) {
        // Already have enough workers, send to gold
        this.harvestAssignments.set(worker.id, 'gold');
        this.sendToHarvest(state, worker, 'gold');
      }
    }
  }

  private sendToHarvest(state: GameState, worker: Unit, resource: 'gold' | 'wood'): void {
    const tileType = resource === 'gold' ? 'gold_mine' : 'forest';
    const target = findNearestResource(state, { x: worker.x, y: worker.y }, tileType as any);
    if (target) {
      worker.targetPos = target;
      worker.path = [];
      worker.state = UnitState.Moving;
      worker.targetId = null;
    }
  }

  private trainWorkers(state: GameState, workers: Unit[]): void {
    const supply = getSupply(state, this.faction);
    if (workers.length >= this.plan.maxWorkers) return;
    if (supply.used >= supply.cap) return;

    const townHalls = [...state.buildings.values()].filter(
      b => b.faction === this.faction && b.type === BuildingType.TownHall && b.state === BuildingState.Complete
    );

    for (const hall of townHalls) {
      if (hall.trainingQueue.length < 1) {
        const stats = UNIT_STATS[UnitType.Worker];
        if (state.resources[this.faction].gold >= stats.goldCost) {
          issueTrainCommand(state, hall.id, UnitType.Worker);
        }
      }
    }
  }

  private buildNext(state: GameState, myBuildings: Building[]): void {
    if (this.buildOrderIndex >= this.buildOrder.length) {
      // After build order, keep building farms and towers
      const supply = getSupply(state, this.faction);
      if (supply.used >= supply.cap - 2) {
        this.tryBuild(state, BuildingType.Farm, myBuildings);
      }
      if (myBuildings.filter(b => b.type === BuildingType.GuardTower).length < 2 + this.difficulty) {
        this.tryBuild(state, BuildingType.GuardTower, myBuildings);
      }
      return;
    }

    const nextType = this.buildOrder[this.buildOrderIndex];

    // Check if we already have this building
    const existing = myBuildings.filter(b => b.type === nextType && b.state !== BuildingState.Destroyed).length;
    const needed = nextType === BuildingType.Farm ? 0 : 1; // Always need more farms

    if (existing > 0 && nextType !== BuildingType.Farm) {
      this.buildOrderIndex++;
      return;
    }

    // Check prerequisites
    if (nextType === BuildingType.LumberMill) {
      const hasBarracks = myBuildings.some(b => b.type === BuildingType.Barracks && b.state === BuildingState.Complete);
      if (!hasBarracks) return;
    }

    // Check resources
    const stats = BUILDING_STATS[nextType];
    if (state.resources[this.faction].gold < stats.goldCost || state.resources[this.faction].wood < stats.woodCost) {
      return;
    }

    if (this.tryBuild(state, nextType, myBuildings)) {
      this.buildOrderIndex++;
    }
  }

  private tryBuild(state: GameState, type: BuildingType, myBuildings: Building[]): boolean {
    // Find an idle worker
    const workers = [...state.units.values()].filter(
      u => u.faction === this.faction && u.type === UnitType.Worker && u.state !== UnitState.Dead
    );
    if (workers.length === 0) return false;

    const worker = workers[0];
    const stats = BUILDING_STATS[type];

    // Find a valid position near the AI base
    const aiBuilding = myBuildings.find(b => b.type === BuildingType.TownHall);
    if (!aiBuilding) return false;

    const baseX = aiBuilding.tileX;
    const baseY = aiBuilding.tileY;

    // Search for a valid build location
    for (let r = 3; r < 15; r++) {
      for (let dy = -r; dy <= r; dy++) {
        for (let dx = -r; dx <= r; dx++) {
          if (Math.abs(dx) !== r && Math.abs(dy) !== r) continue;
          const tx = baseX + dx;
          const ty = baseY + dy;
          if (canPlaceBuilding(state, type, tx, ty, this.faction)) {
            issueBuildCommand(state, worker.id, type, tx, ty);
            return true;
          }
        }
      }
    }

    return false;
  }

  private trainMilitary(state: GameState, military: Unit[]): void {
    const supply = getSupply(state, this.faction);
    const barracks = [...state.buildings.values()].filter(
      b => b.faction === this.faction && b.type === BuildingType.Barracks && b.state === BuildingState.Complete
    );

    const hasLumberMill = [...state.buildings.values()].some(
      b => b.faction === this.faction && b.type === BuildingType.LumberMill && b.state === BuildingState.Complete
    );

    for (const barrack of barracks) {
      if (barrack.trainingQueue.length >= 2) continue;

      // Decide what to train
      let unitType: UnitType;
      const rng = this.rng.next();

      if (hasLumberMill) {
        if (rng < 0.3) unitType = UnitType.Infantry;
        else if (rng < 0.6) unitType = UnitType.Ranged;
        else unitType = UnitType.Heavy;
      } else {
        unitType = UnitType.Infantry;
      }

      const stats = UNIT_STATS[unitType];
      if (state.resources[this.faction].gold >= stats.goldCost &&
        state.resources[this.faction].wood >= stats.woodCost &&
        supply.used + stats.supplyCost <= supply.cap) {
        issueTrainCommand(state, barrack.id, unitType);
      }
    }

    // Also train from Town Hall if we need more workers
    const workers = [...state.units.values()].filter(
      u => u.faction === this.faction && u.type === UnitType.Worker && u.state !== UnitState.Dead
    );
    if (workers.length < this.plan.maxWorkers) {
      const townHalls = [...state.buildings.values()].filter(
        b => b.faction === this.faction && b.type === BuildingType.TownHall && b.state === BuildingState.Complete
      );
      for (const hall of townHalls) {
        if (hall.trainingQueue.length < 1) {
          const wStats = UNIT_STATS[UnitType.Worker];
          if (state.resources[this.faction].gold >= wStats.goldCost && supply.used < supply.cap) {
            issueTrainCommand(state, hall.id, UnitType.Worker);
          }
        }
      }
    }
  }

  private manageAttacks(state: GameState, military: Unit[]): void {
    const now = state.time;

    if (now - this.lastAttackTime < this.plan.attackInterval) return;

    // Only attack if we have enough military
    const idleMilitary = military.filter(u =>
      u.state === UnitState.Idle || u.state === UnitState.Moving
    );

    if (idleMilitary.length < this.plan.attackWaveSize) return;

    // Find player base location
    const playerBuilding = [...state.buildings.values()].find(
      b => b.faction !== this.faction && b.state !== BuildingState.Destroyed
    );

    if (!playerBuilding) return;

    // Send attack force
    const attackForce = idleMilitary.slice(0, this.plan.attackWaveSize);
    const targetX = playerBuilding.tileX;
    const targetY = playerBuilding.tileY;

    for (const unit of attackForce) {
      unit.targetPos = { x: targetX, y: targetY };
      unit.path = [];
      unit.state = UnitState.Moving;
      unit.targetId = null;
    }

    this.lastAttackTime = now;
  }

  private defendBase(state: GameState, myUnits: Unit[]): void {
    // Check if any enemy units are near our buildings
    const myBuildings = [...state.buildings.values()].filter(
      b => b.faction === this.faction && b.state !== BuildingState.Destroyed
    );

    for (const building of myBuildings) {
      const bStats = BUILDING_STATS[building.type];
      const cx = building.tileX + bStats.footprintW / 2;
      const cy = building.tileY + bStats.footprintH / 2;

      // Find nearby enemy units
      for (const unit of state.units.values()) {
        if (unit.faction !== this.faction || unit.state === UnitState.Dead) continue;
        const dist = distance(unit.x, unit.y, cx, cy);
        if (dist <= 10) {
          // Threat detected — pull idle military to defend
          const idleMilitary = myUnits.filter(u =>
            u.type !== UnitType.Worker && (u.state === UnitState.Idle || u.state === UnitState.Moving) && !u.targetId
          );

          for (const defender of idleMilitary) {
            defender.targetId = unit.id;
            defender.state = UnitState.Attacking;
          }
          break;
        }
      }
    }
  }
}

// ─── Canvas 2D Renderer ───

import {
  GameState, Faction, FogState, UnitType, BuildingType, UnitState, BuildingState,
  GameScreen, Unit, Building, TileType,
} from './types';
import {
  TILE_SIZE, TILE_COLORS, TILE_COLORS_DIM, FACTION_COLORS, FACTION_COLORS_DARK,
  UNIT_NAMES, BUILDING_NAMES, UNIT_STATS, BUILDING_STATS, BUILDABLE_TILES,
} from './constants';

const MINIMAP_SIZE = 160;
const TOP_BAR_H = 36;
const BOTTOM_PANEL_H = 160;
const MINIMAP_PAD = 4;

export class Renderer {
  private ctx: CanvasRenderingContext2D;
  private width: number;
  private height: number;
  private canvas: HTMLCanvasElement;

  constructor(canvas: HTMLCanvasElement) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d')!;
    this.width = canvas.width;
    this.height = canvas.height;
  }

  resize(w: number, h: number): void {
    this.width = w;
    this.height = h;
    this.canvas.width = w;
    this.canvas.height = h;
  }

  render(state: GameState): void {
    const ctx = this.ctx;
    ctx.clearRect(0, 0, this.width, this.height);

    switch (state.screen) {
      case GameScreen.Menu:
        this.renderMenu(state);
        break;
      case GameScreen.LevelSelect:
        this.renderLevelSelect(state);
        break;
      case GameScreen.Playing:
        this.renderGame(state);
        break;
      case GameScreen.Victory:
        this.renderGame(state);
        this.renderOverlay(state, 'VICTORY!', '#4488ff');
        break;
      case GameScreen.Defeat:
        this.renderGame(state);
        this.renderOverlay(state, 'DEFEAT', '#ff4444');
        break;
    }
  }

  // ─── Menu screens ───

  private renderMenu(state: GameState): void {
    const ctx = this.ctx;
    ctx.fillStyle = '#1a1a2e';
    ctx.fillRect(0, 0, this.width, this.height);

    ctx.fillStyle = '#e0e0e0';
    ctx.font = 'bold 48px monospace';
    ctx.textAlign = 'center';
    ctx.fillText('WARBAND', this.width / 2, this.height / 3);

    ctx.font = '18px monospace';
    ctx.fillText('A Real-Time Strategy Game', this.width / 2, this.height / 3 + 40);

    ctx.font = '24px monospace';
    ctx.fillStyle = '#88cc88';
    ctx.fillText('Click to Start', this.width / 2, this.height / 2 + 20);

    ctx.font = '14px monospace';
    ctx.fillStyle = '#888';
    ctx.fillText('Seed: ' + state.seed, this.width / 2, this.height - 40);
  }

  private renderLevelSelect(state: GameState): void {
    const ctx = this.ctx;
    ctx.fillStyle = '#1a1a2e';
    ctx.fillRect(0, 0, this.width, this.height);

    ctx.fillStyle = '#e0e0e0';
    ctx.font = 'bold 36px monospace';
    ctx.textAlign = 'center';
    ctx.fillText('SELECT LEVEL', this.width / 2, 60);

    const levels = [
      { name: 'The Plains', size: '32×32', diff: 1 },
      { name: 'River Valley', size: '48×48', diff: 2 },
      { name: 'Highland Pass', size: '64×64', diff: 3 },
      { name: 'Marshlands', size: '80×80', diff: 4 },
      { name: 'The Citadel', size: '96×96', diff: 5 },
    ];

    const startY = 120;
    for (let i = 0; i < levels.length; i++) {
      const lv = levels[i];
      const unlocked = i === 0 || state.levelResults.get(i);
      const y = startY + i * 70;
      const x = this.width / 2;

      ctx.fillStyle = unlocked ? '#2a4a2a' : '#2a2a2a';
      ctx.fillRect(x - 200, y, 400, 55);

      ctx.strokeStyle = unlocked ? '#448844' : '#444';
      ctx.strokeRect(x - 200, y, 400, 55);

      ctx.fillStyle = unlocked ? '#e0e0e0' : '#666';
      ctx.font = 'bold 20px monospace';
      ctx.textAlign = 'center';
      ctx.fillText(`Level ${i + 1}: ${lv.name}`, x, y + 25);

      ctx.font = '14px monospace';
      ctx.fillText(`${lv.size} — Difficulty ${lv.diff}`, x, y + 45);
    }

    ctx.font = '14px monospace';
    ctx.fillStyle = '#888';
    ctx.textAlign = 'center';
    ctx.fillText('Press ESC to return to menu', this.width / 2, this.height - 30);
  }

  // ─── Game rendering ───

  private renderGame(state: GameState): void {
    const ctx = this.ctx;
    const vpX = Math.floor(state.camera.x);
    const vpY = Math.floor(state.camera.y);
    const vpW = Math.floor(this.width / TILE_SIZE);
    const vpH = Math.floor((this.height - TOP_BAR_H - BOTTOM_PANEL_H) / TILE_SIZE);

    // Draw terrain
    this.renderTerrain(state, vpX, vpY, vpW, vpH);

    // Draw buildings
    this.renderBuildings(state, vpX, vpY, vpW, vpH);

    // Draw units
    this.renderUnits(state, vpX, vpY, vpW, vpH);

    // Draw projectiles
    this.renderProjectiles(state, vpX, vpY);

    // Draw corpses
    this.renderCorpses(state, vpX, vpY);

    // Draw fog overlay
    this.renderFog(state, vpX, vpY, vpW, vpH);

    // Draw selection highlights
    this.renderSelection(state, vpX, vpY);

    // Draw build placement preview
    this.renderBuildPreview(state, vpX, vpY);

    // Draw UI
    this.renderTopBar(state);
    this.renderBottomPanel(state);
    this.renderMinimap(state);
  }

  private renderTerrain(state: GameState, vpX: number, vpY: number, vpW: number, vpH: number): void {
    const ctx = this.ctx;
    const offX = -(state.camera.x - vpX) * TILE_SIZE;
    const offY = -(state.camera.y - vpY) * TILE_SIZE + TOP_BAR_H;

    for (let ty = Math.max(0, vpY - 1); ty < Math.min(state.map.height, vpY + vpH + 2); ty++) {
      for (let tx = Math.max(0, vpX - 1); tx < Math.min(state.map.width, vpX + vpW + 2); tx++) {
        const tile = state.map.tiles[ty][tx];
        const sx = (tx - vpX) * TILE_SIZE + offX;
        const sy = (ty - vpY) * TILE_SIZE + offY;
        if (sx < -TILE_SIZE || sx > this.width || sy < TOP_BAR_H - TILE_SIZE || sy > this.height - BOTTOM_PANEL_H) continue;

        const fog = state.fog[ty]?.[tx] ?? FogState.Unexplored;
        let color: string;

        if (fog === FogState.Unexplored) {
          color = '#111';
        } else if (fog === FogState.Explored) {
          color = TILE_COLORS_DIM[tile.type] || '#333';
        } else {
          color = TILE_COLORS[tile.type] || '#888';
        }

        ctx.fillStyle = color;
        ctx.fillRect(sx, sy, TILE_SIZE, TILE_SIZE);

        // Resource amount indicator
        if (fog === FogState.Visible && tile.resourceAmount > 0) {
          if (tile.type === TileType.GoldMine) {
            ctx.fillStyle = '#ff0';
            ctx.fillRect(sx + TILE_SIZE * 0.3, sy + TILE_SIZE * 0.3, TILE_SIZE * 0.4, TILE_SIZE * 0.4);
          } else if (tile.type === TileType.Forest) {
            // Tree shape
            ctx.fillStyle = '#1a3a0e';
            ctx.beginPath();
            ctx.moveTo(sx + TILE_SIZE / 2, sy + TILE_SIZE * 0.1);
            ctx.lineTo(sx + TILE_SIZE * 0.8, sy + TILE_SIZE * 0.9);
            ctx.lineTo(sx + TILE_SIZE * 0.2, sy + TILE_SIZE * 0.9);
            ctx.fill();
          }
        }
      }
    }
  }

  private renderBuildings(state: GameState, vpX: number, vpY: number, vpW: number, vpH: number): void {
    const ctx = this.ctx;

    for (const building of state.buildings.values()) {
      if (building.state === BuildingState.Destroyed) continue;

      const stats = BUILDING_STATS[building.type];
      const bx = building.tileX;
      const by = building.tileY;

      // Check if any part is visible
      let anyVisible = false;
      for (let dy = 0; dy < stats.footprintH; dy++) {
        for (let dx = 0; dx < stats.footprintW; dx++) {
          const tx = bx + dx;
          const ty = by + dy;
          if (tx >= 0 && tx < state.map.width && ty >= 0 && ty < state.map.height) {
            if (state.fog[ty][tx] === FogState.Visible) anyVisible = true;
            if (building.faction === state.playerFaction) anyVisible = true;
          }
        }
      }
      if (!anyVisible) continue;

      // Only draw own buildings or visible enemy buildings
      if (building.faction !== state.playerFaction && !anyVisible) continue;

      const sx = (bx - state.camera.x) * TILE_SIZE;
      const sy = (by - state.camera.y) * TILE_SIZE + TOP_BAR_H;
      const sw = stats.footprintW * TILE_SIZE;
      const sh = stats.footprintH * TILE_SIZE;

      // Building body
      const color = building.faction === state.playerFaction ?
        (building.state === BuildingState.Constructing ? '#666' : FACTION_COLORS[building.faction]) :
        FACTION_COLORS[building.faction];

      ctx.fillStyle = color;
      ctx.fillRect(sx + 2, sy + 2, sw - 4, sh - 4);

      // Building border
      ctx.strokeStyle = building.faction === state.playerFaction ? '#fff' : '#aaa';
      ctx.lineWidth = 1;
      ctx.strokeRect(sx + 2, sy + 2, sw - 4, sh - 4);

      // Building icon/label
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 10px monospace';
      ctx.textAlign = 'center';
      const label = getBuildingLabel(building.type);
      ctx.fillText(label, sx + sw / 2, sy + sh / 2 + 4);

      // Build progress bar
      if (building.state === BuildingState.Constructing) {
        ctx.fillStyle = '#333';
        ctx.fillRect(sx + 4, sy - 8, sw - 8, 4);
        ctx.fillStyle = '#ff0';
        ctx.fillRect(sx + 4, sy - 8, (sw - 8) * building.buildProgress, 4);
      }

      // Health bar
      if (building.hp < building.maxHp) {
        const hpRatio = building.hp / building.maxHp;
        ctx.fillStyle = '#333';
        ctx.fillRect(sx + 4, sy - 4, sw - 8, 3);
        ctx.fillStyle = hpRatio > 0.5 ? '#0f0' : hpRatio > 0.25 ? '#ff0' : '#f00';
        ctx.fillRect(sx + 4, sy - 4, (sw - 8) * hpRatio, 3);
      }

      // Training progress
      if (building.trainingQueue.length > 0) {
        const item = building.trainingQueue[0];
        ctx.fillStyle = '#333';
        ctx.fillRect(sx + 4, sy + sh, sw - 8, 3);
        ctx.fillStyle = '#4af';
        ctx.fillRect(sx + 4, sy + sh, (sw - 8) * item.progress, 3);
      }
    }
  }

  private renderUnits(state: GameState, vpX: number, vpY: number, vpW: number, vpH: number): void {
    const ctx = this.ctx;

    for (const unit of state.units.values()) {
      if (unit.state === UnitState.Dead) continue;

      // Fog check for enemy units
      if (unit.faction !== state.playerFaction) {
        const tx = Math.round(unit.x);
        const ty = Math.round(unit.y);
        if (tx < 0 || tx >= state.map.width || ty < 0 || ty >= state.map.height) continue;
        if (state.fog[ty][tx] !== FogState.Visible) continue;
      }

      const sx = (unit.x - state.camera.x) * TILE_SIZE + TILE_SIZE / 2;
      const sy = (unit.y - state.camera.y) * TILE_SIZE + TOP_BAR_H + TILE_SIZE / 2;

      if (sx < -TILE_SIZE || sx > this.width + TILE_SIZE || sy < TOP_BAR_H - TILE_SIZE || sy > this.height) continue;

      const color = FACTION_COLORS[unit.faction];
      const radius = unit.type === UnitType.Heavy ? 8 : unit.type === UnitType.Worker ? 5 : 6;

      // Unit body
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.arc(sx, sy, radius, 0, Math.PI * 2);
      ctx.fill();

      // Unit outline
      ctx.strokeStyle = '#000';
      ctx.lineWidth = 1;
      ctx.stroke();

      // Unit type indicator
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 7px monospace';
      ctx.textAlign = 'center';
      const symbol = getUnitSymbol(unit.type);
      ctx.fillText(symbol, sx, sy + 3);

      // Carrying resource indicator
      if (unit.carryingAmount > 0) {
        ctx.fillStyle = unit.carryingType === 'gold' ? '#ff0' : '#840';
        ctx.fillRect(sx + radius, sy - radius, 4, 4);
      }

      // Health bar (only if damaged)
      if (unit.hp < unit.maxHp) {
        const hpRatio = unit.hp / unit.maxHp;
        const barW = 16;
        ctx.fillStyle = '#333';
        ctx.fillRect(sx - barW / 2, sy - radius - 6, barW, 3);
        ctx.fillStyle = hpRatio > 0.5 ? '#0f0' : hpRatio > 0.25 ? '#ff0' : '#f00';
        ctx.fillRect(sx - barW / 2, sy - radius - 6, barW * hpRatio, 3);
      }
    }
  }

  private renderProjectiles(state: GameState, vpX: number, vpY: number): void {
    const ctx = this.ctx;

    for (const proj of state.projectiles.values()) {
      const sx = (proj.x - state.camera.x) * TILE_SIZE + TILE_SIZE / 2;
      const sy = (proj.y - state.camera.y) * TILE_SIZE + TOP_BAR_H + TILE_SIZE / 2;

      ctx.fillStyle = FACTION_COLORS[proj.faction];
      ctx.beginPath();
      ctx.arc(sx, sy, 2, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  private renderCorpses(state: GameState, vpX: number, vpY: number): void {
    const ctx = this.ctx;

    for (const corpse of state.corpses) {
      const sx = (corpse.x - state.camera.x) * TILE_SIZE + TILE_SIZE / 2;
      const sy = (corpse.y - state.camera.y) * TILE_SIZE + TOP_BAR_H + TILE_SIZE / 2;
      const alpha = Math.max(0, Math.min(1, corpse.fadeTimer / 3));

      ctx.globalAlpha = alpha;
      ctx.fillStyle = FACTION_COLORS_DARK[corpse.faction];
      ctx.beginPath();
      ctx.arc(sx, sy, 4, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = 1;
    }
  }

  private renderFog(state: GameState, vpX: number, vpY: number, vpW: number, vpH: number): void {
    const ctx = this.ctx;

    for (let ty = Math.max(0, vpY - 1); ty < Math.min(state.map.height, vpY + vpH + 2); ty++) {
      for (let tx = Math.max(0, vpX - 1); tx < Math.min(state.map.width, vpX + vpW + 2); tx++) {
        const fog = state.fog[ty]?.[tx];
        if (fog === FogState.Visible) continue;

        const sx = (tx - state.camera.x) * TILE_SIZE;
        const sy = (ty - state.camera.y) * TILE_SIZE + TOP_BAR_H;

        if (fog === FogState.Unexplored) {
          ctx.fillStyle = '#111';
          ctx.fillRect(sx, sy, TILE_SIZE, TILE_SIZE);
        } else if (fog === FogState.Explored) {
          ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
          ctx.fillRect(sx, sy, TILE_SIZE, TILE_SIZE);
        }
      }
    }
  }

  private renderSelection(state: GameState, vpX: number, vpY: number): void {
    const ctx = this.ctx;

    // Selected units
    for (const id of state.selectedUnitIds) {
      const unit = state.units.get(id);
      if (!unit) continue;

      const sx = (unit.x - state.camera.x) * TILE_SIZE + TILE_SIZE / 2;
      const sy = (unit.y - state.camera.y) * TILE_SIZE + TOP_BAR_H + TILE_SIZE / 2;

      ctx.strokeStyle = '#0f0';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(sx, sy, 10, 0, Math.PI * 2);
      ctx.stroke();
    }

    // Selected building
    if (state.selectedBuildingId !== null) {
      const building = state.buildings.get(state.selectedBuildingId);
      if (building) {
        const stats = BUILDING_STATS[building.type];
        const sx = (building.tileX - state.camera.x) * TILE_SIZE;
        const sy = (building.tileY - state.camera.y) * TILE_SIZE + TOP_BAR_H;
        const sw = stats.footprintW * TILE_SIZE;
        const sh = stats.footprintH * TILE_SIZE;

        ctx.strokeStyle = '#0f0';
        ctx.lineWidth = 2;
        ctx.strokeRect(sx, sy, sw, sh);
      }
    }
  }

  private renderBuildPreview(state: GameState, vpX: number, vpY: number): void {
    if (state.buildMode === null) return;
    // Build preview is handled in input handler via mouse position
  }

  // ─── UI ───

  private renderTopBar(state: GameState): void {
    const ctx = this.ctx;
    const supply = getSupplyForUI(state);

    ctx.fillStyle = '#1a1a2e';
    ctx.fillRect(0, 0, this.width, TOP_BAR_H);

    ctx.fillStyle = '#e0e0e0';
    ctx.font = 'bold 14px monospace';
    ctx.textAlign = 'left';

    const res = state.resources[state.playerFaction];
    ctx.fillText(`💰 ${Math.floor(res.gold)}`, 10, 24);
    ctx.fillText(`🪵 ${Math.floor(res.wood)}`, 120, 24);
    ctx.fillText(`🏠 ${supply.used}/${supply.cap}`, 230, 24);
    ctx.fillText(`⏱ ${Math.floor(state.time)}s`, 360, 24);
    ctx.fillText(`Seed: ${state.seed}`, 460, 24);

    // Speed indicator
    ctx.fillText(state.speed === 2 ? '⏩ 2x' : '▶ 1x', this.width - 80, 24);

    // Pause indicator
    if (state.paused) {
      ctx.fillStyle = '#ff0';
      ctx.fillText('PAUSED', this.width / 2, 24);
    }
  }

  private renderBottomPanel(state: GameState): void {
    const ctx = this.ctx;
    const panelY = this.height - BOTTOM_PANEL_H;

    ctx.fillStyle = '#1a1a2e';
    ctx.fillRect(0, panelY, this.width, BOTTOM_PANEL_H);
    ctx.strokeStyle = '#444';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(0, panelY);
    ctx.lineTo(this.width, panelY);
    ctx.stroke();

    // Minimap area (left side)
    const mmAreaX = MINIMAP_PAD;
    const mmAreaY = panelY + MINIMAP_PAD;
    // Minimap is rendered separately

    // Info panel (right of minimap)
    const infoX = MINIMAP_SIZE + 20;
    const infoY = panelY + 10;

    if (state.selectedUnitIds.length > 0) {
      this.renderUnitInfo(state, infoX, infoY);
    } else if (state.selectedBuildingId !== null) {
      this.renderBuildingInfo(state, infoX, infoY);
    } else {
      ctx.fillStyle = '#888';
      ctx.font = '14px monospace';
      ctx.textAlign = 'left';
      ctx.fillText('Select a unit or building', infoX, infoY + 20);
    }
  }

  private renderUnitInfo(state: GameState, x: number, y: number): void {
    const ctx = this.ctx;
    const unitIds = state.selectedUnitIds;

    if (unitIds.length === 1) {
      const unit = state.units.get(unitIds[0]);
      if (!unit) return;

      ctx.fillStyle = FACTION_COLORS[unit.faction];
      ctx.font = 'bold 16px monospace';
      ctx.textAlign = 'left';
      ctx.fillText(UNIT_NAMES[unit.faction][unit.type], x, y + 16);

      ctx.fillStyle = '#ccc';
      ctx.font = '12px monospace';
      ctx.fillText(`HP: ${unit.hp}/${unit.maxHp}`, x, y + 36);
      ctx.fillText(`ATK: ${unit.attackDamage}  ARM: ${unit.armor}  RNG: ${unit.attackRange}`, x, y + 52);

      const stateText = unit.state === UnitState.Idle ? 'Idle' :
        unit.state === UnitState.Moving ? 'Moving' :
          unit.state === UnitState.Attacking ? 'Attacking' :
            unit.state === UnitState.Harvesting ? 'Harvesting' :
              unit.state === UnitState.Returning ? 'Returning' :
                unit.state === UnitState.Building ? 'Building' :
                  unit.state === UnitState.Repairing ? 'Repairing' : unit.state;
      ctx.fillText(`State: ${stateText}`, x, y + 68);

      if (unit.carryingAmount > 0) {
        ctx.fillText(`Carrying: ${unit.carryingAmount} ${unit.carryingType}`, x, y + 84);
      }
    } else {
      // Multiple units selected
      ctx.fillStyle = '#ccc';
      ctx.font = '14px monospace';
      ctx.textAlign = 'left';
      ctx.fillText(`${unitIds.length} units selected`, x, y + 16);
    }
  }

  private renderBuildingInfo(state: GameState, x: number, y: number): void {
    const ctx = this.ctx;
    const building = state.buildings.get(state.selectedBuildingId!);
    if (!building) return;

    const stats = BUILDING_STATS[building.type];

    ctx.fillStyle = FACTION_COLORS[building.faction];
    ctx.font = 'bold 16px monospace';
    ctx.textAlign = 'left';
    ctx.fillText(BUILDING_NAMES[building.type], x, y + 16);

    ctx.fillStyle = '#ccc';
    ctx.font = '12px monospace';
    ctx.fillText(`HP: ${building.hp}/${building.maxHp}`, x, y + 36);

    if (building.state === BuildingState.Constructing) {
      ctx.fillText(`Building: ${Math.floor(building.buildProgress * 100)}%`, x, y + 52);
    }

    // Training info
    if (building.trainingQueue.length > 0) {
      const item = building.trainingQueue[0];
      ctx.fillText(`Training: ${UNIT_NAMES[building.faction][item.unitType]} (${Math.floor(item.progress * 100)}%)`, x, y + 68);
    }

    // Training buttons (for Town Hall and Barracks)
    if (building.state === BuildingState.Complete) {
      this.renderTrainButtons(state, building, x, y + 90);
    }

    // Build buttons (for worker)
    // This is handled in the unit info for workers
  }

  private renderTrainButtons(state: GameState, building: Building, x: number, y: number): void {
    const ctx = this.ctx;

    if (building.type === BuildingType.TownHall) {
      this.drawTrainButton(state, UnitType.Worker, building, x, y);
    } else if (building.type === BuildingType.Barracks) {
      this.drawTrainButton(state, UnitType.Infantry, building, x, y);

      // Check prerequisites for ranged and heavy
      const hasLumberMill = [...state.buildings.values()].some(
        b => b.faction === building.faction && b.type === BuildingType.LumberMill && b.state === BuildingState.Complete
      );

      if (hasLumberMill) {
        this.drawTrainButton(state, UnitType.Ranged, building, x + 120, y);
        this.drawTrainButton(state, UnitType.Heavy, building, x + 240, y);
      }
    }
  }

  private drawTrainButton(state: GameState, unitType: UnitType, building: Building, x: number, y: number): void {
    const ctx = this.ctx;
    const stats = UNIT_STATS[unitType];
    const supply = getSupplyForUI(state);
    const canAfford = state.resources[state.playerFaction].gold >= stats.goldCost &&
      state.resources[state.playerFaction].wood >= stats.woodCost &&
      supply.used + stats.supplyCost <= supply.cap;
    const queueFull = building.trainingQueue.length >= 5;

    ctx.fillStyle = canAfford && !queueFull ? '#2a4a2a' : '#3a2a2a';
    ctx.fillRect(x, y, 110, 40);
    ctx.strokeStyle = canAfford ? '#4a4' : '#644';
    ctx.lineWidth = 1;
    ctx.strokeRect(x, y, 110, 40);

    ctx.fillStyle = canAfford ? '#e0e0e0' : '#888';
    ctx.font = '10px monospace';
    ctx.textAlign = 'left';
    const name = UNIT_NAMES[state.playerFaction][unitType];
    ctx.fillText(name, x + 4, y + 14);
    ctx.fillText(`G:${stats.goldCost} W:${stats.woodCost}`, x + 4, y + 28);
  }

  private renderMinimap(state: GameState): void {
    const ctx = this.ctx;
    const panelY = this.height - BOTTOM_PANEL_H;
    const mmX = MINIMAP_PAD;
    const mmY = panelY + MINIMAP_PAD;

    // Background
    ctx.fillStyle = '#111';
    ctx.fillRect(mmX, mmY, MINIMAP_SIZE, MINIMAP_SIZE);

    // Scale
    const scaleX = MINIMAP_SIZE / state.map.width;
    const scaleY = MINIMAP_SIZE / state.map.height;

    // Draw tiles
    for (let ty = 0; ty < state.map.height; ty++) {
      for (let tx = 0; tx < state.map.width; tx++) {
        const fog = state.fog[ty]?.[tx];
        if (fog === FogState.Unexplored) continue;

        const tile = state.map.tiles[ty][tx];
        let color: string;
        if (fog === FogState.Explored) {
          color = TILE_COLORS_DIM[tile.type] || '#333';
        } else {
          color = TILE_COLORS[tile.type] || '#888';
        }

        ctx.fillStyle = color;
        ctx.fillRect(
          mmX + tx * scaleX,
          mmY + ty * scaleY,
          Math.ceil(scaleX),
          Math.ceil(scaleY)
        );
      }
    }

    // Draw buildings on minimap
    for (const building of state.buildings.values()) {
      if (building.state === BuildingState.Destroyed) continue;
      const stats = BUILDING_STATS[building.type];
      const bx = building.tileX + stats.footprintW / 2;
      const by = building.tileY + stats.footprintH / 2;
      const fog = state.fog[building.tileY]?.[building.tileX];

      if (building.faction === state.playerFaction || fog === FogState.Visible) {
        ctx.fillStyle = FACTION_COLORS[building.faction];
        ctx.fillRect(
          mmX + bx * scaleX - 1,
          mmY + by * scaleY - 1,
          3, 3
        );
      }
    }

    // Draw units on minimap
    for (const unit of state.units.values()) {
      if (unit.state === UnitState.Dead) continue;
      const tx = Math.round(unit.x);
      const ty = Math.round(unit.y);
      if (tx < 0 || tx >= state.map.width || ty < 0 || ty >= state.map.height) continue;

      if (unit.faction === state.playerFaction) {
        ctx.fillStyle = FACTION_COLORS[unit.faction];
        ctx.fillRect(mmX + tx * scaleX, mmY + ty * scaleY, 2, 2);
      } else if (state.fog[ty][tx] === FogState.Visible) {
        ctx.fillStyle = FACTION_COLORS[unit.faction];
        ctx.fillRect(mmX + tx * scaleX, mmY + ty * scaleY, 2, 2);
      }
    }

    // Draw viewport rectangle
    const vpW = Math.floor((this.width) / TILE_SIZE);
    const vpH = Math.floor((this.height - TOP_BAR_H - BOTTOM_PANEL_H) / TILE_SIZE);
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 1;
    ctx.strokeRect(
      mmX + state.camera.x * scaleX,
      mmY + state.camera.y * scaleY,
      vpW * scaleX,
      vpH * scaleY
    );

    // Border
    ctx.strokeStyle = '#666';
    ctx.lineWidth = 2;
    ctx.strokeRect(mmX, mmY, MINIMAP_SIZE, MINIMAP_SIZE);
  }

  private renderOverlay(state: GameState, text: string, color: string): void {
    const ctx = this.ctx;
    ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
    ctx.fillRect(0, 0, this.width, this.height);

    ctx.fillStyle = color;
    ctx.font = 'bold 64px monospace';
    ctx.textAlign = 'center';
    ctx.fillText(text, this.width / 2, this.height / 2 - 30);

    ctx.fillStyle = '#e0e0e0';
    ctx.font = '24px monospace';
    ctx.fillText('Press ENTER to continue', this.width / 2, this.height / 2 + 40);
  }
}

// ─── Helper functions ───

function getBuildingLabel(type: BuildingType): string {
  switch (type) {
    case BuildingType.TownHall: return 'TH';
    case BuildingType.Farm: return 'FM';
    case BuildingType.Barracks: return 'BK';
    case BuildingType.LumberMill: return 'LM';
    case BuildingType.GuardTower: return 'GT';
    default: return '??';
  }
}

function getUnitSymbol(type: UnitType): string {
  switch (type) {
    case UnitType.Worker: return 'W';
    case UnitType.Infantry: return 'I';
    case UnitType.Ranged: return 'R';
    case UnitType.Heavy: return 'H';
    default: return '?';
  }
}

function getSupplyForUI(state: GameState): { used: number; cap: number } {
  let cap = 0;
  let used = 0;

  for (const building of state.buildings.values()) {
    if (building.faction === state.playerFaction && building.state === BuildingState.Complete) {
      cap += BUILDING_STATS[building.type].supplyProvided;
    }
  }

  for (const unit of state.units.values()) {
    if (unit.faction === state.playerFaction && unit.state !== UnitState.Dead) {
      used += unit.supplyCost;
    }
  }

  return { used, cap };
}

// ─── Input handling ───

import {
  GameState, Faction, UnitType, BuildingType, GameScreen, Vec2, UnitState,
} from './types';
import {
  issueMoveCommand, issueAttackCommand, issueAttackMoveCommand,
  issueHarvestCommand, issueBuildCommand, issueTrainCommand, issueRepairCommand,
  canPlaceBuilding, getSupply,
} from './game';
import {
  TILE_SIZE, MINIMAP_SIZE, TOP_BAR_H, BOTTOM_PANEL_H, BUILDING_STATS,
  UNIT_STATS, UNIT_NAMES, WALKABLE_TILES,
} from './constants';
import { Renderer } from './renderer';

export class InputHandler {
  private canvas: HTMLCanvasElement;
  private renderer: Renderer;
  private keys: Set<string> = new Set();
  private mouseDown: boolean = false;
  private mouseButton: number = 0;
  private mouseX: number = 0;
  private mouseY: number = 0;
  private selectStart: Vec2 | null = null;
  private selectEnd: Vec2 | null = null;
  private isDragging: boolean = false;
  private isMinimapDrag: boolean = false;
  private scrollSpeed: number = 15; // tiles per second
  private buildPlacementPos: Vec2 | null = null;

  constructor(canvas: HTMLCanvasElement, renderer: Renderer) {
    this.canvas = canvas;
    this.renderer = renderer;
  }

  init(state: GameState): void {
    // Keyboard
    window.addEventListener('keydown', (e) => this.onKeyDown(e, state));
    window.addEventListener('keyup', (e) => this.onKeyUp(e));

    // Mouse
    this.canvas.addEventListener('mousedown', (e) => this.onMouseDown(e, state));
    this.canvas.addEventListener('mousemove', (e) => this.onMouseMove(e, state));
    this.canvas.addEventListener('mouseup', (e) => this.onMouseUp(e, state));
    this.canvas.addEventListener('contextmenu', (e) => e.preventDefault());

    // Touch support (basic)
    this.canvas.addEventListener('touchstart', (e) => {
      e.preventDefault();
      const touch = e.touches[0];
      this.onMouseDown({ clientX: touch.clientX, clientY: touch.clientY, button: 0 } as MouseEvent, state);
    });
    this.canvas.addEventListener('touchend', (e) => {
      e.preventDefault();
      this.onMouseUp({ clientX: this.mouseX, clientY: this.mouseY, button: 0 } as MouseEvent, state);
    });
  }

  update(state: GameState, dt: number): void {
    // Scroll with keys
    if (state.screen !== GameScreen.Playing) return;

    const scrollX = (this.keys.has('ArrowRight') ? 1 : 0) - (this.keys.has('ArrowLeft') ? 1 : 0);
    const scrollY = (this.keys.has('ArrowDown') ? 1 : 0) - (this.keys.has('ArrowUp') ? 1 : 0);

    if (scrollX !== 0 || scrollY !== 0) {
      state.camera.x += scrollX * this.scrollSpeed * dt;
      state.camera.y += scrollY * this.scrollSpeed * dt;
    }

    // Edge scrolling
    const edgeMargin = 20;
    if (this.mouseX < edgeMargin && this.mouseX >= 0) {
      state.camera.x -= this.scrollSpeed * dt;
    }
    if (this.mouseX > this.canvas.width - edgeMargin) {
      state.camera.x += this.scrollSpeed * dt;
    }
    if (this.mouseY < TOP_BAR_H + edgeMargin && this.mouseY >= TOP_BAR_H) {
      state.camera.y -= this.scrollSpeed * dt;
    }
    if (this.mouseY > this.canvas.height - BOTTOM_PANEL_H - edgeMargin) {
      state.camera.y += this.scrollSpeed * dt;
    }

    // Clamp camera
    const maxCamX = state.map.width - this.canvas.width / TILE_SIZE;
    const maxCamY = state.map.height - (this.canvas.height - TOP_BAR_H - BOTTOM_PANEL_H) / TILE_SIZE;
    state.camera.x = Math.max(0, Math.min(maxCamX, state.camera.x));
    state.camera.y = Math.max(0, Math.min(maxCamY, state.camera.y));

    // Update build placement position
    if (state.buildMode !== null) {
      this.buildPlacementPos = this.screenToTile(state, this.mouseX, this.mouseY);
      if (this.buildPlacementPos) {
        state.buildValid = canPlaceBuilding(state, state.buildMode,
          this.buildPlacementPos.x, this.buildPlacementPos.y, state.playerFaction);
      }
    }
  }

  private onKeyDown(e: KeyboardEvent, state: GameState): void {
    this.keys.add(e.key);

    // Space = pause
    if (e.key === ' ') {
      state.paused = !state.paused;
      e.preventDefault();
      return;
    }

    // Speed toggle
    if (e.key === '+' || e.key === '=') {
      state.speed = state.speed === 1 ? 2 : 1;
      e.preventDefault();
      return;
    }

    // Escape = cancel build mode / deselect
    if (e.key === 'Escape') {
      if (state.buildMode !== null) {
        state.buildMode = null;
        state.buildValid = false;
      } else if (state.screen === GameScreen.LevelSelect) {
        state.screen = GameScreen.Menu;
      } else {
        state.selectedUnitIds = [];
        state.selectedBuildingId = null;
      }
      return;
    }

    // Enter = advance on victory/defeat
    if (e.key === 'Enter') {
      if (state.screen === GameScreen.Victory || state.screen === GameScreen.Defeat) {
        // Return to level select
        state.screen = GameScreen.LevelSelect;
      }
      return;
    }

    // Control groups
    if (e.ctrlKey && e.key >= '1' && e.key <= '9') {
      // Save control group
      const group = parseInt(e.key);
      state.controlGroups.set(group, {
        unitIds: [...state.selectedUnitIds],
        buildingId: state.selectedBuildingId,
      });
      e.preventDefault();
      return;
    }

    if (!e.ctrlKey && e.key >= '1' && e.key <= '9' && !e.shiftKey) {
      // Load control group (only if not typing)
      const group = parseInt(e.key);
      const cg = state.controlGroups.get(group);
      if (cg) {
        state.selectedUnitIds = [...cg.unitIds];
        state.selectedBuildingId = cg.buildingId;
      }
      return;
    }

    // Hotkeys for training
    if (state.selectedBuildingId !== null) {
      const building = state.buildings.get(state.selectedBuildingId);
      if (building && building.state === 'complete') {
        if (e.key === 'w' || e.key === 'W') {
          if (building.type === BuildingType.TownHall) {
            issueTrainCommand(state, building.id, UnitType.Worker);
          }
        }
        if (e.key === 'i' || e.key === 'I') {
          if (building.type === BuildingType.Barracks) {
            issueTrainCommand(state, building.id, UnitType.Infantry);
          }
        }
        if (e.key === 'r' || e.key === 'R') {
          if (building.type === BuildingType.Barracks) {
            issueTrainCommand(state, building.id, UnitType.Ranged);
          }
        }
        if (e.key === 'h' || e.key === 'H') {
          if (building.type === BuildingType.Barracks) {
            issueTrainCommand(state, building.id, UnitType.Heavy);
          }
        }
      }
    }

    // Build hotkeys for selected worker
    if (state.selectedUnitIds.length === 1) {
      const unit = state.units.get(state.selectedUnitIds[0]);
      if (unit && unit.type === UnitType.Worker) {
        const buildHotkeys: Record<string, BuildingType> = {
          'b': BuildingType.Barracks,
          'f': BuildingType.Farm,
          'l': BuildingType.LumberMill,
          'g': BuildingType.GuardTower,
          't': BuildingType.TownHall,
        };
        const bt = buildHotkeys[e.key.toLowerCase()];
        if (bt) {
          state.buildMode = bt;
          e.preventDefault();
        }
      }
    }

    // A = attack-move
    if (e.key === 'a' || e.key === 'A') {
      // Will be handled on next click as attack-move
      // For now, just set a flag
      this.keys.add('attack-move');
    }

    // S = stop
    if (e.key === 's' || e.key === 'S') {
      for (const id of state.selectedUnitIds) {
        const unit = state.units.get(id);
        if (unit) {
          unit.state = UnitState.Idle;
          unit.targetId = null;
          unit.targetPos = null;
          unit.path = [];
        }
      }
    }
  }

  private onKeyUp(e: KeyboardEvent): void {
    this.keys.delete(e.key);
  }

  private onMouseDown(e: MouseEvent, state: GameState): void {
    this.mouseX = e.clientX;
    this.mouseY = e.clientY;
    this.mouseButton = e.button;

    // Menu click
    if (state.screen === GameScreen.Menu) {
      state.screen = GameScreen.LevelSelect;
      return;
    }

    // Level select click
    if (state.screen === GameScreen.LevelSelect) {
      this.handleLevelSelectClick(e, state);
      return;
    }

    if (state.screen !== GameScreen.Playing) return;

    const panelY = state.canvas ? 0 : 0; // Not needed with new layout

    // Check minimap click
    const mmX = 4;
    const mmY = this.canvas.height - BOTTOM_PANEL_H + 4;
    if (e.clientX >= mmX && e.clientX <= mmX + MINIMAP_SIZE &&
      e.clientY >= mmY && e.clientY <= mmY + MINIMAP_SIZE) {
      this.isMinimapDrag = true;
      this.jumpToMinimapPos(e, state);
      return;
    }

    // Check bottom panel click (train buttons, etc.)
    if (e.clientY >= this.canvas.height - BOTTOM_PANEL_H) {
      this.handlePanelClick(e, state);
      return;
    }

    // Check top bar area
    if (e.clientY < TOP_BAR_H) {
      return;
    }

    if (e.button === 0) {
      // Left click
      if (state.buildMode !== null) {
        // Place building
        const tile = this.screenToTile(state, e.clientX, e.clientY);
        if (tile && state.buildValid) {
          // Find selected worker
          const workerId = state.selectedUnitIds[0];
          if (workerId) {
            issueBuildCommand(state, workerId, state.buildMode, tile.x, tile.y);
          }
          state.buildMode = null;
          state.buildValid = false;
        }
        return;
      }

      // Start box select
      this.selectStart = { x: e.clientX, y: e.clientY };
      this.selectEnd = { x: e.clientX, y: e.clientY };
      this.isDragging = false;
      this.mouseDown = true;
    } else if (e.button === 2) {
      // Right click — issue command
      this.handleRightClick(e, state);
    }
  }

  private onMouseMove(e: MouseEvent, state: GameState): void {
    this.mouseX = e.clientX;
    this.mouseY = e.clientY;

    if (this.isMinimapDrag && this.mouseDown) {
      this.jumpToMinimapPos(e, state);
      return;
    }

    if (this.mouseDown && this.selectStart) {
      this.selectEnd = { x: e.clientX, y: e.clientY };
      const dx = this.selectEnd.x - this.selectStart.x;
      const dy = this.selectEnd.y - this.selectStart.y;
      if (Math.abs(dx) > 5 || Math.abs(dy) > 5) {
        this.isDragging = true;
      }
    }
  }

  private onMouseUp(e: MouseEvent, state: GameState): void {
    this.mouseX = e.clientX;
    this.mouseY = e.clientY;

    if (this.isMinimapDrag) {
      this.isMinimapDrag = false;
      this.mouseDown = false;
      return;
    }

    if (e.button === 0 && this.mouseDown) {
      if (this.isDragging && this.selectStart && this.selectEnd) {
        // Box select
        this.handleBoxSelect(state, e.shiftKey);
      } else {
        // Single click select
        this.handleSingleSelect(e, state, e.shiftKey);
      }
    }

    this.mouseDown = false;
    this.isDragging = false;
    this.selectStart = null;
    this.selectEnd = null;
  }

  private handleSingleSelect(e: MouseEvent, state: GameState, additive: boolean): void {
    const tile = this.screenToTile(state, e.clientX, e.clientY);
    if (!tile) return;

    // Check if clicking on a unit
    const clickedUnit = this.findUnitAtScreenPos(state, e.clientX, e.clientY);
    if (clickedUnit) {
      if (clickedUnit.faction === state.playerFaction) {
        if (!additive) {
          state.selectedUnitIds = [clickedUnit.id];
          state.selectedBuildingId = null;
        } else {
          const idx = state.selectedUnitIds.indexOf(clickedUnit.id);
          if (idx >= 0) {
            state.selectedUnitIds.splice(idx, 1);
          } else {
            state.selectedUnitIds.push(clickedUnit.id);
          }
        }
      }
      return;
    }

    // Check if clicking on a building
    const clickedBuilding = this.findBuildingAtTile(state, tile.x, tile.y);
    if (clickedBuilding && clickedBuilding.faction === state.playerFaction) {
      state.selectedBuildingId = clickedBuilding.id;
      state.selectedUnitIds = [];
      return;
    }

    // Deselect
    if (!additive) {
      state.selectedUnitIds = [];
      state.selectedBuildingId = null;
    }
  }

  private handleBoxSelect(state: GameState, additive: boolean): void {
    if (!this.selectStart || !this.selectEnd) return;

    const x1 = Math.min(this.selectStart.x, this.selectEnd.x);
    const y1 = Math.min(this.selectStart.y, this.selectEnd.y);
    const x2 = Math.max(this.selectStart.x, this.selectEnd.x);
    const y2 = Math.max(this.selectStart.y, this.selectEnd.y);

    const selected: number[] = [];
    for (const unit of state.units.values()) {
      if (unit.faction !== state.playerFaction || unit.state === UnitState.Dead) continue;
      const sx = (unit.x - state.camera.x) * TILE_SIZE + TILE_SIZE / 2;
      const sy = (unit.y - state.camera.y) * TILE_SIZE + TOP_BAR_H + TILE_SIZE / 2;
      if (sx >= x1 && sx <= x2 && sy >= y1 && sy <= y2) {
        selected.push(unit.id);
      }
    }

    if (!additive) {
      state.selectedUnitIds = selected;
      state.selectedBuildingId = null;
    } else {
      state.selectedUnitIds = [...new Set([...state.selectedUnitIds, ...selected])];
    }
  }

  private handleRightClick(e: MouseEvent, state: GameState): void {
    if (state.selectedUnitIds.length === 0 && state.selectedBuildingId === null) return;

    const tile = this.screenToTile(state, e.clientX, e.clientY);
    if (!tile) return;

    // Check if right-clicking on an enemy unit
    const enemyUnit = this.findUnitAtScreenPos(state, e.clientX, e.clientY);
    if (enemyUnit && enemyUnit.faction !== state.playerFaction) {
      issueAttackCommand(state, state.selectedUnitIds, enemyUnit.id);
      return;
    }

    // Check if right-clicking on an enemy building
    const building = this.findBuildingAtTile(state, tile.x, tile.y);
    if (building && building.faction !== state.playerFaction) {
      issueAttackCommand(state, state.selectedUnitIds, building.id);
      return;
    }

    // Check if right-clicking on a resource tile
    if (tile.x >= 0 && tile.x < state.map.width && tile.y >= 0 && tile.y < state.map.height) {
      const mapTile = state.map.tiles[tile.y][tile.x];

      if (mapTile.type === 'gold_mine' || mapTile.type === 'forest') {
        // Harvest command (for workers)
        const workers = state.selectedUnitIds.filter(id => {
          const u = state.units.get(id);
          return u && u.type === UnitType.Worker;
        });
        if (workers.length > 0) {
          issueHarvestCommand(state, workers, tile.x, tile.y);
          return;
        }
      }

      // Check if right-clicking on own damaged building (for repair)
      if (building && building.faction === state.playerFaction && building.hp < building.maxHp) {
        issueRepairCommand(state, state.selectedUnitIds, building.id);
        return;
      }
    }

    // Default: move command
    const isAttackMove = this.keys.has('a') || this.keys.has('A') || this.keys.has('attack-move');
    if (isAttackMove) {
      issueAttackMoveCommand(state, state.selectedUnitIds, tile.x, tile.y);
    } else {
      issueMoveCommand(state, state.selectedUnitIds, tile.x, tile.y);
    }
  }

  private handlePanelClick(e: MouseEvent, state: GameState): void {
    const panelY = this.canvas.height - BOTTOM_PANEL_H;
    const infoX = MINIMAP_SIZE + 20;
    const infoY = panelY + 10;

    // Check train buttons
    if (state.selectedBuildingId !== null) {
      const building = state.buildings.get(state.selectedBuildingId);
      if (!building || building.state !== 'complete') return;

      const btnY = infoY + 90;
      const btnW = 110;
      const btnH = 40;

      if (building.type === BuildingType.TownHall) {
        // Worker button
        if (e.clientX >= infoX && e.clientX <= infoX + btnW &&
          e.clientY >= btnY && e.clientY <= btnY + btnH) {
          issueTrainCommand(state, building.id, UnitType.Worker);
        }
      } else if (building.type === BuildingType.Barracks) {
        // Infantry button
        if (e.clientX >= infoX && e.clientX <= infoX + btnW &&
          e.clientY >= btnY && e.clientY <= btnY + btnH) {
          issueTrainCommand(state, building.id, UnitType.Infantry);
        }

        const hasLumberMill = [...state.buildings.values()].some(
          b => b.faction === building.faction && b.type === BuildingType.LumberMill && b.state === 'complete'
        );

        if (hasLumberMill) {
          // Ranged button
          if (e.clientX >= infoX + 120 && e.clientX <= infoX + 120 + btnW &&
            e.clientY >= btnY && e.clientY <= btnY + btnH) {
            issueTrainCommand(state, building.id, UnitType.Ranged);
          }
          // Heavy button
          if (e.clientX >= infoX + 240 && e.clientX <= infoX + 240 + btnW &&
            e.clientY >= btnY && e.clientY <= btnY + btnH) {
            issueTrainCommand(state, building.id, UnitType.Heavy);
          }
        }
      }
    }

    // Build buttons for selected worker
    if (state.selectedUnitIds.length === 1) {
      const unit = state.units.get(state.selectedUnitIds[0]);
      if (unit && unit.type === UnitType.Worker) {
        const buildBtns = [
          { key: 't', type: BuildingType.TownHall, label: 'Town Hall (T)' },
          { key: 'f', type: BuildingType.Farm, label: 'Farm (F)' },
          { key: 'b', type: BuildingType.Barracks, label: 'Barracks (B)' },
          { key: 'l', type: BuildingType.LumberMill, label: 'Lumber Mill (L)' },
          { key: 'g', type: BuildingType.GuardTower, label: 'Guard Tower (G)' },
        ];

        const startY = panelY + 90;
        for (let i = 0; i < buildBtns.length; i++) {
          const btnX = infoX + i * 100;
          const btnY = startY + 25;
          if (e.clientX >= btnX && e.clientX <= btnX + 95 &&
            e.clientY >= btnY && e.clientY <= btnY + 30) {
            state.buildMode = buildBtns[i].type;
          }
        }
      }
    }
  }

  private handleLevelSelectClick(e: MouseEvent, state: GameState): void {
    const levels = 5;
    const startY = 120;
    for (let i = 0; i < levels; i++) {
      const y = startY + i * 70;
      const x = this.canvas.width / 2;
      if (e.clientX >= x - 200 && e.clientX <= x + 200 &&
        e.clientY >= y && e.clientY <= y + 55) {
        const unlocked = i === 0 || state.levelResults.get(i);
        if (unlocked) {
          // Start this level
          const newSeed = state.campaignSeed + i * 1000;
          const newState = createNewGame(newSeed, state.playerFaction, i + 1);
          Object.assign(state, newState);
          state.screen = GameScreen.Playing;
        }
      }
    }
  }

  private jumpToMinimapPos(e: MouseEvent, state: GameState): void {
    const mmX = 4;
    const mmY = this.canvas.height - BOTTOM_PANEL_H + 4;
    const relX = (e.clientX - mmX) / MINIMAP_SIZE;
    const relY = (e.clientY - mmY) / MINIMAP_SIZE;

    const vpW = this.canvas.width / TILE_SIZE;
    const vpH = (this.canvas.height - TOP_BAR_H - BOTTOM_PANEL_H) / TILE_SIZE;

    state.camera.x = Math.max(0, Math.min(state.map.width - vpW, relX * state.map.width - vpW / 2));
    state.camera.y = Math.max(0, Math.min(state.map.height - vpH, relY * state.map.height - vpH / 2));
  }

  private screenToTile(state: GameState, sx: number, sy: number): Vec2 | null {
    const x = Math.floor((sx / TILE_SIZE) + state.camera.x);
    const y = Math.floor(((sy - TOP_BAR_H) / TILE_SIZE) + state.camera.y);
    return { x, y };
  }

  private findUnitAtScreenPos(state: GameState, sx: number, sy: number): Unit | null {
    const tileX = (sx / TILE_SIZE) + state.camera.x;
    const tileY = ((sy - TOP_BAR_H) / TILE_SIZE) + state.camera.y;

    let closest: Unit | null = null;
    let closestDist = 0.5; // selection radius in tiles

    for (const unit of state.units.values()) {
      if (unit.state === UnitState.Dead) continue;
      if (unit.faction !== state.playerFaction) {
        // Only show visible enemies
        const tx = Math.round(unit.x);
        const ty = Math.round(unit.y);
        if (tx < 0 || tx >= state.map.width || ty < 0 || ty >= state.map.height) continue;
        if (state.fog[ty][tx] !== FogState.Visible) continue;
      }
      const dist = Math.sqrt((unit.x - tileX) ** 2 + (unit.y - tileY) ** 2);
      if (dist < closestDist) {
        closestDist = dist;
        closest = unit;
      }
    }

    return closest;
  }

  private findBuildingAtTile(state: GameState, tx: number, ty: number): Building | null {
    for (const building of state.buildings.values()) {
      if (building.state === BuildingState.Destroyed) continue;
      const stats = BUILDING_STATS[building.type];
      if (tx >= building.tileX && tx < building.tileX + stats.footprintW &&
        ty >= building.tileY && ty < building.tileY + stats.footprintH) {
        return building;
      }
    }
    return null;
  }

  // Expose drag selection rect for rendering
  getSelectionRect(): { x1: number; y1: number; x2: number; y2: number } | null {
    if (this.isDragging && this.selectStart && this.selectEnd) {
      return {
        x1: this.selectStart.x,
        y1: this.selectStart.y,
        x2: this.selectEnd.x,
        y2: this.selectEnd.y,
      };
    }
    return null;
  }

  getMousePos(): Vec2 {
    return { x: this.mouseX, y: this.mouseY };
  }
}

